using FluentAssertions;
using UnitTests.Parser.Census;

namespace Planetfall.Tests.Parser;

/// <summary>
///     Every interaction in Planetfall that changes the game, from <c>interactions.planetfall.json</c>,
///     each checked through the production parser. The file is not written by hand: it is what the game
///     itself answers (see <see cref="InteractionSet" />), regenerated by the explicit test below.
/// </summary>
[TestFixture]
public class InteractionSetTests
{
    private const string FileName = "interactions.planetfall.json";

    private static readonly InteractionCensus Census = new(PlanetfallCensus.Game);

    private static IEnumerable<Interaction> All()
    {
        return InteractionSet.Load(typeof(InteractionSetTests).Assembly, FileName);
    }

    [TestCaseSource(nameof(All))]
    public async Task EveryWording_ThroughTheProductionParser_DoesWhatTheGameDoes(Interaction interaction)
    {
        var problems = await InteractionSet.Check(Census, interaction,
            (verb, noun) => InteractionSet.ProductionParser(PlanetfallCensus.Game, verb, noun));

        problems.Should().BeEquivalentTo(Array.Empty<string>());
    }

    /// <summary>
    ///     Everything here compares the state of one fresh game with the state of another, so two fresh
    ///     games have to be the same game. A game that rolls dice as it starts - a random time of day, a
    ///     battery's charge - makes every turn look like an effect.
    /// </summary>
    [Test]
    public async Task TwoFreshGames_AreInTheSameState()
    {
        var where = new CensusContext("DeckNine", null);

        var once = InteractionCensus.Fingerprint(await Census.StateAfterDoingNothing(where, "door"));
        var again = InteractionCensus.Fingerprint(await Census.StateAfterDoingNothing(where, "door"));
        again.Should().Be(once, "a turn in which nothing happens ends in the same place every time");

        once = InteractionCensus.Fingerprint(await Census.StateAfterDoingNothing(where, "door", true));
        again = InteractionCensus.Fingerprint(await Census.StateAfterDoingNothing(where, "door", true));
        again.Should().Be(once, "and so it does with every room and item loaded");
    }

    /// <summary>
    ///     A death starts the game over with new objects, which roll their dice again in the middle of
    ///     the turn. Whichever word kills, the player ends in the same restarted game - or one fatal
    ///     action reads as a different interaction for every verb that does it.
    /// </summary>
    [Test]
    public async Task EveryFatalWord_EndsInTheSameRestartedGame()
    {
        var where = new CensusContext("BioLockEast", null);

        var opened = await Census.Probe(where, "open", "door");
        var pried = await Census.Probe(where, "pry", "door");

        opened.Response.Should().Contain("Bio-Lab", "opening the bio-lock's inner door unprotected is fatal");
        InteractionCensus.Fingerprint(pried.State).Should().Be(InteractionCensus.Fingerprint(opened.State));

        var again = await Census.Probe(where, "open", "door");
        InteractionCensus.Fingerprint(again.State).Should().Be(InteractionCensus.Fingerprint(opened.State));
    }

    [Test]
    [Explicit("Rewrites interactions.planetfall.json from what the game answers today. Long on one core; to use " +
              "several, set INTERACTION_SET_PART to 1/4, 2/4 ... in as many shells, then run the merge below")]
    public async Task RegenerateTheInteractionSet()
    {
        TestContext.Out.WriteLine(
            await InteractionSet.Regenerate(Census, "Planetfall.Tests", FileName, TestContext.Progress.WriteLine));
    }

    [Test]
    [Explicit("Writes interactions.planetfall.json from the parts RegenerateTheInteractionSet left behind")]
    public void MergeTheInteractionSetParts()
    {
        TestContext.Out.WriteLine(InteractionSet.MergeParts("Planetfall.Tests", FileName));
    }
}
